pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] calldata tos, uint v, uint decimals) public {
        vm.assume(tos.length > 0);
        // deploy a reverter helper so that a subcall can fail
        Reverter reverter = new Reverter();
        // build an array that replaces each tos[i] with the reverter address to guarantee a failing low-level call
        address[] memory failingTos = new address[](tos.length);
        for (uint i = 0; i < tos.length; i++) {
            failingTos[i] = address(reverter);
        }

        bool ret;
        bool ok;
        // capture whether the call reverts
        try c.transfer(from, caddress, failingTos, v, decimals) returns (bool r) {
            ret = r;
            ok = true;
        } catch {
            ok = false;
        }

        // For a correct contract, a failing subcall MUST revert -> ok == false.
        // The mutant returns false without reverting -> ok == true and ret == false.
        // General property: if the call completes (ok) then ret must be true.
        assertTrue(!ok || ret);
    }
}

contract Reverter { fallback() external payable { revert(); } }

