import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        // Restrict domain to avoid overflow, zero-length array, and excessive loop iterations, but keep wide enough for the bug
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        _decimals = bound(_decimals, 0, 77); // keep multiplication safe from overflow
        v = bound(v, 0, type(uint).max / (10 ** _decimals));
        // Adversarial helper that logs the amount sent through transferFrom
        LoggingHelper helper = new LoggingHelper();
        // Execute via the reference C; if it reverts, the test succeeds trivially for the reference, but we care about non-reverting cases for the bug
        vm.assume(from != address(0) && caddress == address(helper));
        bool refOk;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool res) { refOk = res; } catch { refOk = false; }
        vm.assume(refOk); // only consider inputs where reference succeeds
        // The helper has logged the amount
        uint loggedAmount = helper.lastAmount();
        // Assert that the logged amount equals the expected reference amount (v * 10^_decimals)
        assertTrue(loggedAmount == v * (10 ** _decimals));
    }
}

contract LoggingHelper {
    uint public lastAmount;
    function transferFrom(address, address, uint amount) external returns (bool) {
        lastAmount = amount;
        return true;
    }
