import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        // The bug only distinguishes when _tos is empty; remove the original require lets the call succeed.
        // We let the fuzzer explore arrays of any length, including empty ones.
        // No adversarial helper is needed because the difference is a pure logic gate.

        // For safety, ensure v and decimals stay within reasonable range to avoid overflow
        // but do not restrict _tos length – the fuzzer will find the empty case.
        v = bound(v, 0, type(uint).max / (10 ** 18));
        _decimals = bound(_decimals, 0, 18);

        // The reference contract MUST revert when _tos.length == 0.
        // The mutant does NOT revert, returning true instead.
        bool ok;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }

        // The general property: if _tos is empty, the call must revert.
        // If it is non‑empty, both versions behave the same and return true.
        // Therefore: assertTrue((_tos.length == 0) ? (!ok) : ok);
        // This holds for EVERY admissible input on the reference, but the buggy version
        // returns ok == true even when _tos.length == 0, breaking the first branch.
        assertTrue(_tos.length == 0 ? !ok : ok);
    }
}

