pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint v, uint _decimals) public {
        // Restrict to admissible domain: at least one recipient, decimals in a reasonable range, v non-zero
        vm.assume(_tos.length > 0);
        vm.assume(_decimals > 0);
        vm.assume(_decimals <= 18);
        vm.assume(v > 0 && v < type(uint256).max / (10 ** _decimals)); // avoid overflow in mul for reference check
        // Deploy a reverter callee: any call to it will revert
        Reverter reverter = new Reverter();
        address caddress = address(reverter);
        // Reference C: _value = v * 10**_decimals > 0, low-level call to reverter will revert.
        // But the difference is in the semantics: we need a callee that succeeds for non-zero and reverts for zero.
        // Actually, both will revert on Reverter. Need a callee that distinguishes the transferred amount.
        // A callee that reverts when value is zero and succeeds otherwise.
        ConditionalReverter conditional = new ConditionalReverter();
        bool okCorrect;
        try c.transfer(from, address(conditional), _tos, v, _decimals) returns (bool ret) { okCorrect = ret; } catch { okCorrect = false; }
        // Property: the correct contract never reverts (returns true) for admissible inputs
        assertTrue(okCorrect);
    }
}

contract ConditionalReverter {
    fallback() external payable {
        // Decode the value from the transferFrom call data (4-byte selector + address + address + uint256)
        // The value is the last 32 bytes of the calldata
        assembly {
            let value := calldataload(100) // 4 + 32 + 32 = 68; next 32 start at 68, but offset 100? Let's recalc.
            // transferFrom(address,address,uint256) calldata layout:
            // 0x23b872dd (4 bytes) + from (32 bytes, left-padded) + to (32 bytes, left-padded) + value (32 bytes)
            // total offset: 4 + 32 + 32 = 68 for value start at byte 68
            if iszero(value) { revert(0, 0) }
        }
    }
}

